# -*- coding: utf-8 -*-
import os, re, shutil

ROOT = "gelen"
OUT = "arsiv"
EXTS = {".jpg", ".jpeg", ".png", ".mp4", ".mov"}
DATE_RE = re.compile(r"(20\d{6})")          # YYYYMMDD, 20 ile başlar
DATE2_RE = re.compile(r"(20\d{2})-(\d{2})-(\d{2})")  # YYYY-MM-DD

def parse_date(name):
    m = DATE_RE.search(name)
    if m:
        return m.group(1)
    m = DATE2_RE.search(name)
    if m:
        return m.group(1) + m.group(2) + m.group(3)
    return None

results = []
for dirpath, dirnames, filenames in os.walk(ROOT):
    for fn in filenames:
        full = os.path.join(dirpath, fn)
        ext = os.path.splitext(fn)[1].lower()
        if ext not in EXTS:
            continue
        d = parse_date(fn)
        if d:
            dest_dir = os.path.join(OUT, d[:4], d[4:6])
        else:
            dest_dir = os.path.join(OUT, "tarihsiz")
        os.makedirs(dest_dir, exist_ok=True)
        shutil.move(full, os.path.join(dest_dir, fn))
        results.append((full, dest_dir + os.sep + fn))

for a, b in results:
    print(f"{a} -> {b}")

